package library.flow; public class EdmondsKarp {public int maxFlow(int[][] c,int s,int t){int n=c.length,flow=0;while(true){int[] p=new int[n];for(int i=0;i<n;i++)p[i]=-1;int[] q=new int[n];int h=0,r=0;q[r++]=s;p[s]=s;while(h<r&&p[t]<0){int u=q[h++];for(int v=0;v<n;v++)if(p[v]<0&&c[u][v]>0){p[v]=u;q[r++]=v;}}if(p[t]<0)break;int f=Integer.MAX_VALUE;for(int v=t;v!=s;v=p[v])f=Math.min(f,c[p[v]][v]);for(int v=t;v!=s;v=p[v]){c[p[v]][v]-=f;c[v][p[v]]+=f;}flow+=f;}return flow;}}
